{
  "mcpServers": {
    "playwright": {
      "command": "cmd",
      "args": ["/c", "npx", "-y", "@playwright/mcp@latest", "--output-dir", ".playwright-mcp"]
    }
  }
}

{
  "enabledMcpjsonServers": ["playwright"],
  "permissions": {
    "deny": [
      "Edit(platform/templates/**)",
      "Write(platform/templates/**)"
    ]
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "platform/schemas/journal-event.schema.json",
  "title": "AI QA Execution Journal — Event",
  "description": "One entry in platform/tasks/<task-name>/journal/execution-log.json → entries[]. Shared by every workflow stage. Records what actually happened; never contains fabricated runtime values. Supersedes the v0.1.0 inline 'entryFormat' descriptor in the task template (see docs/architecture/ai-qa-execution-journal.md).",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version", "event_id", "event_type", "step_number", "attempt",
    "workflow_run_id", "task_id", "timestamp",
    "stage_id", "stage_name", "skill_name", "skill_version",
    "prompt_id", "prompt_version", "trigger",
    "input_references", "source_references",
    "tools_used", "mcp_used", "actions", "output_artifacts",
    "assumptions", "gaps", "open_questions",
    "validation", "status", "approval_required", "approval_key",
    "next_stage", "errors", "notes"
  ],
  "properties": {
    "schema_version": { "const": "1.0.0" },

    "event_id": {
      "type": "string", "pattern": "^EVT-[0-9]{4,}$",
      "description": "Sequential within the task journal: EVT-0001, EVT-0002, …"
    },
    "event_type": {
      "enum": ["stage_execution", "revision_request", "approval_decision"],
      "description": "stage_execution = the stage ran (success or failure). revision_request = the human asked for changes. approval_decision = the human replied to a gate (accepted or not)."
    },
    "step_number": { "type": "integer", "minimum": 1, "description": "Position of this event in the journal (= numeric part of event_id)." },
    "attempt": { "type": "integer", "minimum": 1, "description": "Attempt number of this stage within the workflow run. Increments on every re-run/revision." },

    "workflow_run_id": { "type": "string", "pattern": "^RUN-[0-9]{8}T[0-9]{6}Z$" },
    "task_id": { "type": "string" },
    "timestamp": { "type": "string", "format": "date-time", "description": "UTC, taken from the system clock at the moment of the event. Never estimated." },

    "stage_id": { "type": "string", "description": "Stage id from platform/workflows/*.yaml" },
    "stage_name": { "type": "string" },
    "skill_name": { "type": "string", "description": "Skill id from platform/registry/skills.yaml" },
    "skill_version": { "type": "string" },
    "prompt_id": { "type": ["string", "null"], "description": "References journal/prompts.json. null only for events where no prompt was executed (e.g. approval_decision)." },
    "prompt_version": { "type": ["string", "null"] },
    "prompt_variables": { "type": "object", "additionalProperties": { "type": "string" }, "description": "Values substituted into the prompt's {{variables}} for this run." },

    "trigger": {
      "type": "object",
      "additionalProperties": false,
      "required": ["reason", "initiated_by"],
      "properties": {
        "reason": { "type": "string", "description": "Why this step was executed." },
        "initiated_by": { "enum": ["user", "workflow", "skill"] },
        "user_message": { "type": ["string", "null"], "description": "Verbatim human message that caused the event (instruction, change request, or gate reply)." }
      }
    },

    "input_references": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["path", "role", "status"],
        "properties": {
          "path": { "type": "string" },
          "role": { "enum": ["task_prd", "task_metadata", "knowledge_base", "supporting_document", "upstream_artifact", "previous_version_of_output", "user_feedback", "prompt"] },
          "status": { "enum": ["read", "missing", "unreadable", "not_applicable"] },
          "sha256": { "type": ["string", "null"] },
          "referenced_by": { "type": ["string", "null"], "description": "Where the input was referenced from, e.g. 'PRD §4.2'." }
        }
      }
    },
    "source_references": {
      "type": "array",
      "description": "Sources the output cites (e.g. PRD sections used for traceability).",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["path", "sections"],
        "properties": {
          "path": { "type": "string" },
          "sections": { "type": "array", "items": { "type": "string" } }
        }
      }
    },

    "tools_used": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["tool", "purpose"],
        "properties": {
          "tool": { "type": "string" },
          "purpose": { "type": "string" },
          "targets": { "type": "array", "items": { "type": "string" } }
        }
      }
    },
    "mcp_used": {
      "type": "object",
      "additionalProperties": false,
      "required": ["used", "servers", "intentionally_not_used"],
      "description": "Records MCP usage AND deliberate non-usage, so the HTML journal can show 'MCP: None' with the reason.",
      "properties": {
        "used": { "type": "boolean" },
        "servers": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["server", "purpose"],
            "properties": {
              "server": { "type": "string" },
              "tools": { "type": "array", "items": { "type": "string" } },
              "purpose": { "type": "string" }
            }
          }
        },
        "intentionally_not_used": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["server", "reason"],
            "properties": { "server": { "type": "string" }, "reason": { "type": "string" } }
          }
        }
      }
    },

    "actions": { "type": "array", "items": { "type": "string" }, "description": "Ordered list of what was actually done." },
    "decisions": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["decision", "rationale"],
        "properties": { "decision": { "type": "string" }, "rationale": { "type": "string" } }
      }
    },

    "output_artifacts": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["path", "operation"],
        "properties": {
          "path": { "type": "string" },
          "operation": { "enum": ["created", "updated", "unchanged"] },
          "artifact_status": { "type": ["string", "null"], "description": "e.g. draft, approved" },
          "sha256": { "type": ["string", "null"] },
          "summary": { "type": ["string", "null"], "description": "e.g. section item counts" }
        }
      }
    },

    "assumptions": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "summary", "status"],
        "properties": {
          "id": { "type": "string" },
          "summary": { "type": "string" },
          "status": { "enum": ["confirmed", "unconfirmed"] }
        }
      }
    },
    "gaps": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "summary"],
        "properties": {
          "id": { "type": "string" },
          "summary": { "type": "string" },
          "related": { "type": ["string", "null"] }
        }
      }
    },
    "open_questions": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "question", "owner"],
        "properties": {
          "id": { "type": "string" },
          "question": { "type": "string" },
          "related": { "type": ["string", "null"] },
          "owner": { "type": ["string", "null"], "description": "null unless a source or the human explicitly named one." }
        }
      }
    },

    "validation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["performed", "overall", "checks"],
      "properties": {
        "performed": { "type": "boolean" },
        "overall": { "enum": ["pass", "fail", "partial", "not_applicable"] },
        "checks": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["check_id", "description", "result"],
            "properties": {
              "check_id": { "type": "string" },
              "description": { "type": "string" },
              "result": { "enum": ["pass", "fail", "not_applicable"] },
              "notes": { "type": ["string", "null"] }
            }
          }
        }
      }
    },

    "status": {
      "enum": ["awaiting_approval", "revision_requested", "approved", "approval_not_accepted", "failed"],
      "description": "State of the stage after this event."
    },
    "stop_reason": { "type": ["string", "null"], "description": "Why the workflow stopped after this event." },
    "approval_required": { "type": "boolean" },
    "approval_key": { "type": ["string", "null"], "description": "The literal key that unlocks the next stage." },
    "approval_outcome": { "enum": ["accepted", "not_accepted", null], "description": "Only for approval_decision events." },

    "next_stage": {
      "type": "object",
      "additionalProperties": false,
      "required": ["stage_id", "unlocked", "condition"],
      "properties": {
        "stage_id": { "type": ["string", "null"] },
        "unlocked": { "type": "boolean" },
        "condition": { "type": "string", "description": "What must happen before the next stage may start." }
      }
    },

    "errors": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["code", "message"],
        "properties": {
          "code": { "type": "string" },
          "message": { "type": "string" },
          "resolution": { "type": ["string", "null"] }
        }
      }
    },
    "fixes": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["description"],
        "properties": {
          "error_code": { "type": ["string", "null"] },
          "description": { "type": "string" }
        }
      }
    },
    "evidence": { "type": "array", "items": { "type": "string" }, "description": "Paths to screenshots, logs, traces, reports. Empty when the stage produces none." },
    "notes": { "type": ["string", "null"] }
  }
}

