writes.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "platform/schemas/workflow-run.schema.json",
  "title": "Workflow Run Context",
  "description": "platform/tasks/<task-name>/journal/workflow-run.json. OWNED BY THE WORKFLOW ORCHESTRATION LAYER. The orchestrator creates the workflow_run_id when a workflow execution starts. Every stage of that execution shares it. Skills only READ active_run_id and never create, change or invent it.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schema", "owner", "task_id", "active_run_id", "runs"],
  "properties": {
    "schema": { "const": "platform/schemas/workflow-run.schema.json" },
    "owner": { "type": "string" },
    "task_id": { "type": ["string", "null"] },
    "active_run_id": {
      "type": ["string", "null"],
      "pattern": "^RUN-[A-Za-z0-9-]+$",
      "description": "The run that stages currently belong to. null = no active run, so no stage may execute."
    },
    "runs": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["workflow_run_id", "workflow_id", "workflow_version", "started_at", "initiated_by", "status"],
        "properties": {
          "workflow_run_id": { "type": "string", "pattern": "^RUN-[A-Za-z0-9-]+$", "description": "Recommended format: RUN-001, RUN-002, … sequential per task." },
          "workflow_id": { "type": "string" },
          "workflow_version": { "type": "string" },
          "started_at": { "type": "string", "format": "date-time" },
          "initiated_by": { "type": "string" },
          "status": { "enum": ["active", "completed", "aborted"] },
          "ended_at": { "type": ["string", "null"], "format": "date-time" },
          "notes": { "type": ["string", "null"] }
        }
      }
    }
  }
}

const P = 'C:/Users/QC User/Desktop/FinalAI/AI-QA-Platform/';
const fs = require('fs'), cp = require('child_process');
const Ajv = require('ajv/dist/2020'), fmt = require('ajv-formats');
const ajv = new Ajv({ allErrors: true, strict: false }); fmt(ajv);
const J = f => JSON.parse(fs.readFileSync(P + f, 'utf8'));
const Y = f => JSON.parse(cp.execSync(`npx -y js-yaml "${P + f}"`).toString());
let fails = 0; const ok = (name, cond, extra = '') => { console.log((cond ? 'PASS ' : 'FAIL ') + name, extra); if (!cond) fails++; };

const ev = ajv.compile(J('platform/schemas/journal-event.schema.json'));
const pr = ajv.compile(J('platform/schemas/prompt-record.schema.json'));
const wr = ajv.compile(J('platform/schemas/workflow-run.schema.json'));
ok('3 schemas compile', true);
ok('template workflow-run.json valid vs schema', wr(J('platform/templates/task-template/journal/workflow-run.json')), JSON.stringify(wr.errors || ''));
ok('synthetic run context valid', wr({ schema: 'platform/schemas/workflow-run.schema.json', owner: 'x', task_id: 't', active_run_id: 'RUN-001', runs: [{ workflow_run_id: 'RUN-001', workflow_id: 'default-qa-workflow', workflow_version: '0.3.0', started_at: '2000-01-01T00:00:00Z', initiated_by: 'x', status: 'active' }] }));

// Fill synthetic runtime values in memory (never written to the project)
function fill(t, type) {
  const e = JSON.parse(JSON.stringify(t));
  Object.assign(e, { event_id: 'EVT-0001', step_number: 1, attempt: 1, workflow_run_id: 'RUN-001', task_id: 'synthetic', timestamp: '2000-01-01T00:00:00Z' });
  if (!e.decisions) e.decisions = [];
  if (typeof e.revision === 'string' || e.revision === undefined) e.revision = null;
  if (e.prompt_variables) for (const k in e.prompt_variables) e.prompt_variables[k] = 's';
  e.trigger.user_message = 's'; e.trigger.reason = 's';
  for (const r of e.input_references) { r.path = 's'; r.status = 'read'; if ('notes' in r) r.notes = null; }
  for (const o of e.output_artifacts) { o.path = 's'; o.operation = 'created'; o.artifact_status = 'draft'; if ('artifact_version' in o) o.artifact_version = '1.0.0'; o.sha256 = null; o.summary = null; }
  e.validation.overall = 'pass'; for (const c of e.validation.checks) c.result = 'pass';
  if (type === 'approval_decision') { e.status = 'approved'; e.approval_outcome = 'accepted'; e.next_stage.unlocked = true; e.stop_reason = null; }
  return e;
}
for (const skill of ['prd-generation', 'project-context']) {
  const t = J(`.claude/skills/${skill}/journal-event.template.json`);
  for (const type of ['stage_execution', 'revision_request', 'approval_decision']) {
    const e = fill(type === 'stage_execution' ? t[type] : { ...t.stage_execution, ...t[type] }, type);
    ok(`${skill} ${type} template → valid event`, ev(e), JSON.stringify(ev.errors || ''));
  }
  const se = fill(t.stage_execution, 'stage_execution');
  ok(`${skill} mcp_used = None + playwright intentionally_not_used`, se.mcp_used.used === false && se.mcp_used.servers.length === 0 && se.mcp_used.intentionally_not_used[0].server === 'playwright');
}
// revision object + negative cases
const base = fill(J('.claude/skills/prd-generation/journal-event.template.json').stage_execution, 'stage_execution');
ok('revision event (1.0.0→1.1.0) valid', ev({ ...base, attempt: 2, revision: { artifact_path: 's', version_before: '1.0.0', version_after: '1.1.0', reason: 's', changed_sections: ['§8'], revision_request_event_id: 'EVT-0002', prompt_version_changed: false, previous_prompt_version: null } }), JSON.stringify(ev.errors || ''));
ok('bad run id format rejected', !ev({ ...base, workflow_run_id: 'run 1' }));
const noMcp = { ...base }; delete noMcp.mcp_used; ok('missing mcp_used rejected', !ev(noMcp));
const noOutcome = { ...base }; delete noOutcome.approval_outcome; ok('missing approval_outcome rejected', !ev(noOutcome));
ok('prompt record valid', pr({ prompt_id: 'prd-generation', prompt_version: '1.0.0', skill_name: 'prd-generation', source_path: 's', sha256: 'a'.repeat(64), captured_at: '2000-01-01T00:00:00Z', first_used_by_event_id: 'EVT-0001', content: 's' }));

// Registry / prompt / skill / workflow consistency
const reg = Y('platform/registry/skills.yaml'), wf = Y('platform/workflows/default-qa-workflow.yaml');
const impl = reg.skills.filter(s => s.implemented).map(s => s.id);
ok('only prd-generation + project-context implemented', JSON.stringify(impl) === '["prd-generation","project-context"]', impl);
for (const id of impl) {
  const s = reg.skills.find(x => x.id === id), prm = fs.readFileSync(P + s.prompt_path, 'utf8'), sk = fs.readFileSync(P + s.skill_path, 'utf8');
  const tpl = J(s.journal.event_template);
  ok(`${id}: prompt id/version match registry`, prm.includes('prompt_id: ' + s.prompt_id) && prm.includes('prompt_version: ' + s.prompt_version));
  ok(`${id}: SKILL.md versions match registry`, sk.includes('Skill version | `' + s.version + '`') && sk.includes('`prompt_version: ' + s.prompt_version + '`'));
  ok(`${id}: event template versions match`, tpl.stage_execution.skill_version === s.version && tpl.stage_execution.prompt_version === s.prompt_version && tpl.stage_execution.approval_key === s.approval_key);
  ok(`${id}: approval key in SKILL/prompt/workflow`, sk.includes(s.approval_key) && prm.includes(s.approval_key) && wf.stages.find(x => x.id === id).gate.approval_key === s.approval_key);
  ['skill_path', 'prompt_path', 'output_template'].forEach(k => ok(`${id}: ${k} exists`, fs.existsSync(P + s[k])));
}
const order = wf.stages.map(s => s.id);
