const fs = require('fs');
const p = 'C:/Users/QC User/Desktop/FinalAI/AI-QA-Platform/platform/schemas/journal-event.schema.json';
const s = JSON.parse(fs.readFileSync(p, 'utf8'));
const P = s.properties;
const nstr = { type: ['string', 'null'] };
const strArr = { type: 'array', items: { type: 'string' } };

P.schema_version = { const: '1.2.0' };

P.status.enum = ['awaiting_approval', 'revision_requested', 'approved', 'approval_not_accepted', 'blocked', 'failed'];
P.status.description = "State of the stage after this event. 'blocked' = a prerequisite was not met, so the stage did not start (no tools/MCP used, no artifact). 'failed' = the stage started but could not complete.";

P.mcp_used.properties.servers.items.properties.version = { type: ['string', 'null'], description: 'Server package/version as reported, or null if not determinable.' };

// Structured evidence (replaces string list)
P.evidence = {
  type: 'array',
  description: 'Evidence items produced by this event. Empty when the stage produces none. Every item is real: captured from the system/tool, or explicitly not_captured with a reason.',
  items: {
    type: 'object', additionalProperties: false,
    required: ['id', 'type', 'capture_status', 'source_action', 'related_observations', 'path', 'captured_at'],
    properties: {
      id: { type: 'string', pattern: '^EVD-[0-9]{3,}$' },
      type: { enum: ['screenshot', 'accessibility_snapshot', 'element_attributes', 'url', 'page_title', 'network', 'api_response', 'console', 'browser_state', 'log', 'report', 'other'] },
      capture_status: { enum: ['captured', 'not_captured'] },
      source_action: { type: ['integer', 'string', 'null'], description: 'mcp_actions[].seq (or tool/step description) that produced it.' },
      related_observations: strArr,
      path: { ...nstr, description: 'Task-relative file path, or null if not captured / inline.' },
      original_path: { ...nstr, description: 'Where the tool wrote it before being moved into the task (e.g. .playwright-mcp/...).' },
      sha256: nstr,
      captured_at: { type: ['string', 'null'], format: 'date-time', description: 'System/tool timestamp; null if unavailable.' },
      redactions: { ...nstr, description: 'What was redacted (e.g. auth token), if anything.' },
      notes: { ...nstr, description: 'Required when capture_status is not_captured: the actual reason.' }
    }
  }
};

const extra = {
  mcp_actions: {
    type: 'array',
    description: 'Ordered log of MCP tool calls actually performed (e.g. browser opened, URL visited, form submitted, snapshot captured). Empty when no MCP was used.',
    items: {
      type: 'object', additionalProperties: false,
      required: ['seq', 'server', 'tool', 'action', 'result'],
      properties: {
        seq: { type: 'integer', minimum: 1 },
        server: { type: 'string' },
        tool: { type: 'string', description: 'Exact MCP tool name as invoked.' },
        action: { type: 'string', description: 'Plain-language description of what was done.' },
        target: { ...nstr, description: 'URL, element description, or value category (secrets never recorded).' },
        area: { ...nstr, description: 'Scope area explored (e.g. PC SA-002).' },
        data_changing: { type: 'boolean', description: 'true if the action created/changed/deleted application data.' },
        human_confirmed: { type: ['boolean', 'null'], description: 'For destructive/irreversible/bulk actions: whether explicit human confirmation was obtained.' },
        result: { enum: ['success', 'error', 'blocked', 'no_effect'] },
        timestamp: { type: ['string', 'null'], format: 'date-time' },
        observations: strArr,
        evidence_ids: strArr,
        notes: nstr
      }
    }
  },
  observations: {
    type: 'array',
    description: 'Summary copies of the artifact observations (full detail lives in the artifact), so the HTML journal can navigate Observation → Classification → Evidence → Report.',
    items: {
      type: 'object', additionalProperties: false,
      required: ['id', 'area', 'classification', 'summary', 'sources', 'evidence_ids', 'report_ref'],
      properties: {
        id: { type: 'string', pattern: '^OBS-[0-9]{3,}$' },
        area: { type: 'string' },
        classification: { enum: ['MATCH', 'FINDING', 'GAP', 'QUESTION', 'POTENTIAL BUG'] },
        class_item_id: { ...nstr, description: 'FND-/XGAP-/XQ-/PB- id, null for MATCH.' },
        summary: { type: 'string' },
        sources: { ...strArr, description: "Upstream references, e.g. 'PC EB-003'; empty when ProjectContext is silent." },
        evidence_ids: strArr,
        report_ref: { type: 'string', description: "Artifact location, e.g. 'exploration/ExplorationReport.md §7 FND-002'." },
        status: { enum: ['active', 'withdrawn'], description: 'withdrawn observations keep their id.' }
      }
    }
  },
  classifications: {
    type: ['object', 'null'],
    additionalProperties: false,
    required: ['MATCH', 'FINDING', 'GAP', 'QUESTION', 'POTENTIAL BUG'],
    description: 'Counts per classification across active observations.',
    properties: Object.fromEntries(['MATCH', 'FINDING', 'GAP', 'QUESTION', 'POTENTIAL BUG'].map(k => [k, { type: 'integer', minimum: 0 }]))
  },
  candidate_locators: {
    type: 'array',
    items: {
      type: 'object', additionalProperties: false,
      required: ['id', 'element', 'related_observations'],
      properties: {
        id: { type: 'string', pattern: '^LOC-[0-9]{3,}$' },
        element: { type: 'string' },
        page: nstr,
        stable_id: nstr,
        xpath_attribute: { ...nstr, description: 'Observed attribute name and value, e.g. name="username". Never framework code.' },
        stability: nstr,
        related_observations: strArr,
        evidence_ids: strArr
      }
    }
  },
  coverage: {
    type: ['object', 'null'],
    additionalProperties: false,
    required: ['areas_explored', 'flows_explored', 'pages_visited', 'not_explored', 'limits'],
    properties: {
      areas_explored: strArr,
      flows_explored: strArr,
      pages_visited: { ...strArr, description: 'URLs actually visited.' },
      out_of_scope_followed: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['area', 'reason'], properties: { area: { type: 'string' }, reason: { type: 'string' } } } },
      not_explored: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['area', 'reason'], properties: { area: { type: 'string' }, reason: { type: 'string' } } } },
      limits: strArr,
      started_at: { type: ['string', 'null'], format: 'date-time' },
      ended_at: { type: ['string', 'null'], format: 'date-time' }
    }
  }
};

// insert extras after output_artifacts, keep order readable
const out = {};
for (const [k, v] of Object.entries(P)) { out[k] = v; if (k === 'output_artifacts') Object.assign(out, extra); }
s.properties = out;
s.description = "One entry in platform/tasks/<task-name>/journal/execution-log.json → entries[]. Shared by every workflow stage. Records what actually happened; never contains fabricated runtime values. Optional stage-specific blocks (mcp_actions, observations, classifications, candidate_locators, coverage) are used by stages that produce them (e.g. exploration). See docs/architecture/ai-qa-execution-journal.md.";
fs.writeFileSync(p, JSON.stringify(s, null, 2) + '\n');
console.log('schema 1.2.0 written; properties:', Object.keys(out).length);

const P = 'C:/Users/QC User/Desktop/FinalAI/AI-QA-Platform/';
const fs = require('fs'), cp = require('child_process'), path = require('path');
const Ajv = require('ajv/dist/2020'), fmt = require('ajv-formats');
const ajv = new Ajv({ allErrors: true, strict: false }); fmt(ajv);
const J = f => JSON.parse(fs.readFileSync(P + f, 'utf8'));
const T = f => fs.readFileSync(P + f, 'utf8');
const Y = f => JSON.parse(cp.execSync(`npx -y js-yaml "${P + f}"`).toString());
let fails = 0; const ok = (n, c, x = '') => { console.log((c ? 'PASS ' : 'FAIL ') + n, c ? '' : x); if (!c) fails++; };

const schema = J('platform/schemas/journal-event.schema.json');
const ev = ajv.compile(schema);
ajv.compile(J('platform/schemas/prompt-record.schema.json'));
const wr = ajv.compile(J('platform/schemas/workflow-run.schema.json'));
ok('schemas compile; event schema_version 1.2.0', schema.properties.schema_version.const === '1.2.0');

// schema-aware synthetic filler (in memory only)
const samples = { '^EVT-[0-9]{4,}$': 'EVT-0001', '^RUN-[A-Za-z0-9-]+$': 'RUN-001', '^OBS-[0-9]{3,}$': 'OBS-001', '^EVD-[0-9]{3,}$': 'EVD-001', '^LOC-[0-9]{3,}$': 'LOC-001' };
const isPh = v => typeof v === 'string' && v.startsWith('<runtime');
function sample(sch) {
  if (!sch) return 's';
  if (sch.enum) return sch.enum.find(x => x !== null);
  const t = Array.isArray(sch.type) ? sch.type.filter(x => x !== 'null')[0] : sch.type;
  if (sch.pattern && samples[sch.pattern]) return samples[sch.pattern];
  if (sch.format === 'date-time') return '2000-01-01T00:00:00Z';
  if (t === 'integer') return 1; if (t === 'boolean') return false; if (t === 'object') return null;
  return 's';
}
function fill(v, sch) {
  if (isPh(v)) return sample(sch);
  if (Array.isArray(v)) return v.map(x => fill(x, sch && sch.items));
  if (v && typeof v === 'object') { const o = {}; for (const k in v) { if (k === '_about') continue; o[k] = fill(v[k], sch && sch.properties && sch.properties[k]); } return o; }
  if (v === null && sch) { const t = Array.isArray(sch.type) ? sch.type : [sch.type]; if (!t.includes('null') && !(sch.enum || []).includes(null)) return sample(sch); }
  return v;
}
const COMMON = ['event_id', 'step_number', 'attempt', 'workflow_run_id', 'task_id', 'timestamp', 'decisions', 'revision', 'prompt_variables'];
function build(t, key) {
  const base = { ...t[key] };
  for (const k of COMMON) if (!(k in base) && k in t.stage_execution) base[k] = t.stage_execution[k];
  if (typeof base.revision === 'string') base.revision = null;
  return fill(base, schema);
}
for (const skill of ['prd-generation', 'project-context', 'exploration']) {
  const t = J(`.claude/skills/${skill}/journal-event.template.json`);
  for (const key of Object.keys(t).filter(k => k !== '_about')) {
    const e = build(t, key); ok(`${skill}.${key} → valid v1.2.0 event`, ev(e), JSON.stringify(ev.errors));
  }
}
const ex = J('.claude/skills/exploration/journal-event.template.json');
const good = build(ex, 'stage_execution');
ok('exploration: MCP Playwright recorded', good.mcp_used.used === true && good.mcp_used.servers[0].server === 'playwright');
ok('exploration blocked: MCP Not used + reason, status blocked, no artifacts', (() => { const b = build(ex, 'stage_execution_blocked'); return b.mcp_used.used === false && b.mcp_used.intentionally_not_used[0].server === 'playwright' && b.status === 'blocked' && b.output_artifacts.length === 0 && b.mcp_actions.length === 0; })());
const neg = (name, mut) => { const e = JSON.parse(JSON.stringify(good)); mut(e); ok('rejects ' + name, !ev(e)); };
neg('invalid classification label', e => e.observations[0].classification = 'BUG');
neg('CONFIRMED BUG label', e => e.observations[0].classification = 'CONFIRMED BUG');
neg('evidence without capture_status', e => delete e.evidence[0].capture_status);
neg('evidence as plain string (pre-1.2.0)', e => e.evidence = ['file.png']);
neg('observation without evidence_ids', e => delete e.observations[0].evidence_ids);
neg('mcp action without tool', e => delete e.mcp_actions[0].tool);
neg('bad OBS id', e => e.observations[0].id = 'OB-1');
neg('missing classification count', e => delete e.classifications.QUESTION);

// registry / prompt / skill / workflow consistency
const reg = Y('platform/registry/skills.yaml'), wf = Y('platform/workflows/default-qa-workflow.yaml');
const impl = reg.skills.filter(s => s.implemented).map(s => s.id);
ok('implemented = prd-generation, project-context, exploration only', JSON.stringify(impl) === '["prd-generation","project-context","exploration"]', impl);
for (const id of impl) {
  const s = reg.skills.find(x => x.id === id), prm = T(s.prompt_path), sk = T(s.skill_path), tpl = J(s.journal.event_template);
  ok(`${id}: prompt id/version = registry`, prm.includes('prompt_id: ' + s.prompt_id) && prm.includes('prompt_version: ' + s.prompt_version));
  ok(`${id}: SKILL.md versions = registry`, sk.includes('Skill version | `' + s.version + '`') && sk.includes('`prompt_version: ' + s.prompt_version + '`'));
  ok(`${id}: event template versions/key = registry`, Object.keys(tpl).filter(k => k !== '_about').every(k => tpl[k].skill_version === s.version && tpl[k].approval_key === s.approval_key && tpl[k].schema_version === '1.2.0'));
  ok(`${id}: gate key in workflow`, wf.stages.find(x => x.id === id).gate.approval_key === s.approval_key);
  ['skill_path', 'prompt_path', 'output_template'].forEach(k => ok(`${id}: ${k} exists`, fs.existsSync(P + s[k])));
}
const st = id => wf.stages.find(x => x.id === id);
ok('workflow order prd → pc → exploration → test-design', wf.stages.slice(0, 4).map(s => s.id).join() === 'prd-generation,project-context,exploration,test-design');
ok('exploration requires PROJECT_CONTEXT_APPROVED', st('exploration').requires_approval_of[0] === 'project-context' && st('project-context').gate.unlocks[0] === 'exploration');
ok('EXPLORATION_APPROVED unlocks test-design', st('exploration').gate.approval_key === 'EXPLORATION_APPROVED' && st('exploration').gate.unlocks[0] === 'test-design' && st('test-design').requires_approval_of[0] === 'exploration');
ok('exploration MCP = playwright; registry mcp_dependency', st('exploration').mcp === 'playwright' && reg.skills.find(s => s.id === 'exploration').mcp_dependency.server === 'playwright');
ok('test-design not implemented, no SKILL.md', !st('test-design').implemented && !fs.existsSync(P + '.claude/skills/test-design'));
ok('run id owned by orchestration', wf.workflow.run.owner === 'orchestration' && wf.workflow.run.skills_may_create_run_id === false);
ok('no stale Exploration.md paths in workflow', !T('platform/workflows/default-qa-workflow.yaml').includes('Exploration.md'));

// exploration skill content rules
const SK = T('.claude/skills/exploration/SKILL.md'), PR = T('.claude/prompts/exploration.md'), RT = T('.claude/skills/exploration/ExplorationReport.template.md');
const all = SK + PR + RT;
ok('no platform_core_data / modules paths', !/platform_core_data|modules\//.test(all));
ok('no OrangeHRM references', !/orangehrm/i.test(all));
ok('no "Stage N" numbering in contract', !/Stage [0-9]/.test(SK + PR));
