let fails = 0, n = 0; const ok = (id, name, c, x = '') => { n++; console.log(`${c ? 'PASS' : 'FAIL'} ${id} ${name}${c ? '' : '  → ' + x}`); if (!c) fails++; };

// ---------- V1 schemas ----------
const schema = J('platform/schemas/journal-event.schema.json');
let ev; try { ev = mk().compile(schema); mk().compile(J('platform/schemas/prompt-record.schema.json')); mk().compile(J('platform/schemas/workflow-run.schema.json')); ok('V01', 'all 3 schemas compile', true); } catch (e) { ok('V01', 'schemas compile', false, e.message); }
ok('V02', 'event schema unchanged at 1.4.0 enum (no schema change needed)', JSON.stringify(schema.properties.schema_version.enum) === '["1.2.0","1.3.0","1.4.0"]');

// ---------- V3 templates validate (in-memory synthetic fill) ----------
const samples = { '^EVT-[0-9]{4,}$': 'EVT-0001', '^RUN-[A-Za-z0-9-]+$': 'RUN-001', '^OBS-[0-9]{3,}$': 'OBS-001', '^EVD-[0-9]{3,}$': 'EVD-001', '^LOC-[0-9]{3,}$': 'LOC-001', '^TC-[0-9]{3,}$': 'TC-001', '^TA-[0-9]{3,}$': 'TA-001', '^CG-[0-9]{3,}$': 'CG-001', '^DATA-[0-9]{3,}$': 'DATA-001', '^BUG-[0-9]{3,}$': 'BUG-001', '^EXEC-[0-9]{3,}$': 'EXEC-001', '^DEV-[0-9]{3,}$': 'DEV-001', '^TCI-[0-9]{3,}$': 'TCI-001' };
const isPh = v => typeof v === 'string' && v.startsWith('<runtime');
function resolve(s, v) { if (!s) return s; if (s.$ref) return resolve(schema.$defs[s.$ref.split('/').pop()], v); if (s.anyOf && v && typeof v === 'object') { const k = Object.keys(v); for (const a of s.anyOf) { const r = resolve(a, v); if (r && r.properties && k.every(x => x in r.properties)) return r; } } return s; }
function sample(s) { if (!s) return 's'; if (s.enum) return s.enum.find(x => x !== null); const t = Array.isArray(s.type) ? s.type.filter(x => x !== 'null')[0] : s.type; if (s.pattern && samples[s.pattern]) return samples[s.pattern]; if (s.format === 'date-time') return '2000-01-01T00:00:00Z'; if (t === 'integer') return 1; if (t === 'boolean') return false; if (t === 'object') return null; return 's'; }
function fill(v, s) { s = resolve(s, v); if (isPh(v)) return sample(s); if (Array.isArray(v)) return v.map(x => fill(x, s && s.items)); if (v && typeof v === 'object') { const o = {}; for (const k in v) { if (k === '_about') continue; o[k] = fill(v[k], s && s.properties && s.properties[k]); } return o; } if (v === null && s && s.type) { const t = Array.isArray(s.type) ? s.type : [s.type]; if (!t.includes('null') && !(s.enum || []).includes(null)) return sample(s); } return v; }
