const build = (t, k) => { const b = { ...t[k] }; for (const c of COMMON) if (!(c in b) && c in t.stage_execution) b[c] = t.stage_execution[c]; if (typeof b.revision === 'string') b.revision = null; return fill(b, schema); };
let tplOk = true, tplErr = '';
for (const s of ['prd-generation', 'project-context', 'exploration', 'test-design', 'manual-execution']) { const t = J(`.claude/skills/${s}/journal-event.template.json`); for (const k of Object.keys(t).filter(k => k !== '_about')) { if (!ev(build(t, k))) { tplOk = false; tplErr += `${s}.${k}: ${JSON.stringify(ev.errors)} `; } } }
ok('V03', 'all 19 event-template variants (5 skills) validate against the schema', tplOk, tplErr);

// ---------- V4 registry/prompt/skill/template consistency ----------
const reg = Y('platform/registry/skills.yaml'), wf = Y('platform/workflows/default-qa-workflow.yaml');
const impl = reg.skills.filter(s => s.implemented).map(s => s.id);
ok('V04', 'implemented skills unchanged in set (5), test-review still planned / no SKILL.md', JSON.stringify(impl) === '["prd-generation","project-context","exploration","test-design","manual-execution"]' && !fs.existsSync(P + '.claude/skills/test-review') && !fs.existsSync(P + '.claude/prompts/test-review.md'), impl);
let cons = true, cerr = '';
for (const id of impl) { const s = reg.skills.find(x => x.id === id), pr = T(s.prompt_path), sk = T(s.skill_path), tp = J(s.journal.event_template), ks = Object.keys(tp).filter(k => k !== '_about');
  const c = pr.includes('prompt_version: ' + s.prompt_version) && sk.includes('Skill version | `' + s.version + '`') && sk.includes('`prompt_version: ' + s.prompt_version + '`') && ks.every(k => tp[k].skill_version === s.version && (!tp[k].prompt_id || tp[k].prompt_version === s.prompt_version) && tp[k].approval_key === s.approval_key) && wf.stages.find(x => x.id === id).gate.approval_key === s.approval_key;
  if (!c) { cons = false; cerr += id + ' '; } }
ok('V05', 'registry ↔ SKILL.md ↔ prompt ↔ event template ↔ workflow versions/keys consistent for all implemented skills', cons, cerr);
ok('V06', 'versions bumped: test-design 1.0.1 (prompt 1.0.0 unchanged), manual-execution 1.1.0 (prompt 1.1.0 with changelog)', reg.skills.find(s => s.id === 'test-design').version === '1.0.1' && reg.skills.find(s => s.id === 'test-design').prompt_version === '1.0.0' && reg.skills.find(s => s.id === 'manual-execution').version === '1.1.0' && /1\.1\.0: Require a current TEST_REVIEW_APPROVED/.test(T('.claude/prompts/manual-execution.md')));
