ok('V08', 'stage order: prd(1) → pc(2) → exploration(3) → test-design(4) → test-review(5) → manual-execution(6) → automation-generation(7) → automation-execution(8) → self-healing(9) → reporting(10)', wf.stages.map(s => s.id).join() === 'prd-generation,project-context,exploration,test-design,test-review,manual-execution,automation-generation,automation-execution,self-healing,reporting' && wf.stages.every((s, i) => s.order === i + 1));
ok('V09', 'test-review mandatory, requires TEST_DESIGN_APPROVED, gate TEST_REVIEW_APPROVED unlocks [manual-execution, automation-generation]', st('test-review').mandatory === true && st('test-review').optional === undefined && st('test-review').on_mandatory_path === undefined && st('test-review').requires_approval_of.join() === 'test-design' && st('test-review').gate.hard_stop === true && st('test-review').gate.approval_key === 'TEST_REVIEW_APPROVED' && st('test-review').gate.unlocks.join() === 'manual-execution,automation-generation');
ok('V10', 'test-design gate unlocks ONLY test-review', st('test-design').gate.unlocks.join() === 'test-review');
ok('V11', 'manual-execution depends on + requires approval of test-review', st('manual-execution').depends_on.join() === 'test-review' && st('manual-execution').requires_approval_of.join() === 'test-review');
ok('V12', 'automation-generation requires test-review AND manual-execution, same_review_as manual-execution', st('automation-generation').requires_approval_of.join() === 'test-review,manual-execution' && st('automation-generation').same_review_as === 'manual-execution');
// graph bypass check: edges upstream→downstream from depends_on, requires_approval_of, gate.unlocks
