module.exports = function verify(baseline) {
  const out = {};
  for (const [f, fn] of Object.entries(reversers)) {
    try { const h = sha(fn()); out[f] = h === baseline[f] ? "match" : "MISMATCH"; }
    catch (e) { out[f] = "ERROR " + e.message; }
  }
  return out;
};

