// Render test for the simplified journal: loads index.html from disk in jsdom and exercises all 3 sections.
const { JSDOM, VirtualConsole } = require("jsdom");
const fs = require("fs");
const DIR = "C:/Users/QC User/Desktop/FinalAI/AI-QA-Platform/reports/qa-journal/";
const PAGE = DIR + "index.html";
const errors = [];
const vc = new VirtualConsole();
vc.on("jsdomError", (e) => errors.push("jsdomError: " + e.message));
vc.on("error", (e) => errors.push("console.error: " + e));
const R = [];
const ok = (id, d, c, detail = "") => R.push({ id, d, c: !!c, detail });

JSDOM.fromFile(PAGE, { runScripts: "dangerously", resources: "usable", virtualConsole: vc, url: "file:///" + PAGE.replace(/ /g, "%20"),
  beforeParse(w) { w.scrollTo = () => {}; w.HTMLElement.prototype.scrollIntoView = function () {}; } }).then((dom) => {
  dom.window.addEventListener("load", () => {
    const w = dom.window, doc = w.document, D = w.QA_JOURNAL_DATA;
    const go = (hh) => { w.location.hash = hh; w.dispatchEvent(new w.HashChangeEvent("hashchange")); };
    const view = () => doc.getElementById("view");
    const dlg = doc.getElementById("viewer");
    const uiText = () => { const c = view().cloneNode(true); c.querySelectorAll("pre, .md, .code").forEach((n) => n.remove()); return c.textContent; };
