      ok("T02", "No warning banner and no label badges in the main view", !doc.querySelector(".banner") && view().querySelectorAll(".badge").length === 0);
      const css = fs.readFileSync(DIR + "assets/app.css", "utf8");
      ok("T03", "Dark design is fixed (color-scheme dark, no light/system theme switching)", /color-scheme: dark/.test(css) && !/prefers-color-scheme|data-theme/.test(css) && /--bg: #0e1116/.test(css));
      // overview
      const ov = view().textContent;
      const impl = D.stages.filter((s) => s.definition_status === "implemented").length;
      ok("T04", "Overview has the 3 status cards", view().querySelectorAll(".status-card").length === 3);
