      ok("T08", "Overview never claims tests passed or ran", !/\b(tests? (passed|ran)|passed \d|executed \d+ test)/i.test(ov));
      ok("T09", "Overview links to Next Step", !!view().querySelector('a[href="#/next"]'));
      // history
      go("#/history");
      const items = view().querySelectorAll("details.hist-item");
      ok("T10", `History lists all ${D.activities.length} requests, all collapsed by default`, items.length === D.activities.length && [...items].every((d) => !d.open));
      const first = items[0]; first.open = true; first.dispatchEvent(new w.Event("toggle"));
      ok("T11", "Opening an item shows Your request / What Claude changed / Result, technical records still collapsed", /Your request/.test(first.textContent) && /What Claude changed/.test(first.textContent) && /Result/.test(first.textContent) && first.querySelector("details.sec") && !first.querySelector("details.sec").open);
      ok("T12", "Request preview is the start of the exact recorded prompt", first.querySelector("pre.code").textContent.startsWith(D.activities[0].prompt.text.slice(0, 200)));
      let exact = 0;
      for (const a of D.activities) {
        go("#/history/" + a.id);
        const it = doc.getElementById("act-" + a.id);
        [...it.querySelectorAll("button")].find((b) => b.textContent === "Read the full request").click();
        if (dlg.querySelector("pre").textContent === a.prompt.text) exact++;
      }
      ok("T13", "“Read the full request” shows every original prompt exactly", exact === D.activities.length, `${exact}/${D.activities.length}`);
      go("#/history/ACT-09");
      const a9 = doc.getElementById("act-ACT-09");
      ok("T14", "Deep link opens ACT-09; its changed files and result are shown", a9.open && a9.querySelectorAll(".part .items li").length > 0 && a9.querySelector(".md"));
      [...a9.querySelectorAll("button")].find((b) => b.textContent === "As written").click();
      ok("T15", "“As written” opens the recorded file content", dlg.hasAttribute("open") && dlg.textContent.length > 200);
      a9.querySelector("details.sec").open = true;
      ok("T16", "Technical records keep every command, with checks and outputs openable", a9.querySelectorAll("details.sec .items li").length === D.activities[8].commands.length + D.activities[8].errors.length);
      const last = D.activities[D.activities.length - 1];
      go("#/history/" + last.id);
      ok("T17", `${last.id} (in progress) says it has no final result; ACT-10 has one`, /No final result yet/.test(doc.getElementById("act-" + last.id).textContent) && !!D.activities[9].final_report);
      go("#/history");
      const s = view().querySelector("input.search"); s.value = "test-review"; s.dispatchEvent(new w.Event("input"));
      const n = view().querySelectorAll("details.hist-item").length;
      ok("T18", "Search narrows the history", n > 0 && n < D.activities.length, `${n} match`);
      // next step
