      ok("T21", "Next Step explains the PRD_APPROVED stop afterwards", /PRD_APPROVED/.test(nx));
      // about dialog
      doc.getElementById("about-btn").click();
      ok("T22", "About dialog shows data sources and what is not included", /Not included/.test(dlg.textContent) && dlg.textContent.includes(D.provenance.transcript.sha256));
      // Arabic
      doc.getElementById("lang-btn").click();
      ok("T23", "Arabic: dir=rtl, lang=ar, Arabic tabs", doc.documentElement.dir === "rtl" && doc.documentElement.lang === "ar" && /تاريخ المشروع/.test(doc.querySelector("nav.tabs").textContent));
      go("#/history/ACT-03");
      const ar3 = doc.getElementById("act-ACT-03");
      ok("T24", "Arabic history keeps the original prompt unchanged and left-to-right", /طلبك/.test(ar3.textContent) && ar3.querySelector("pre.code").getAttribute("dir") === "ltr" && ar3.querySelector("pre.code").textContent.startsWith(D.activities[2].prompt.text.slice(0, 100)));
      doc.getElementById("lang-btn").click();
      ok("T25", "Back to English: ltr", doc.documentElement.dir === "ltr");
      // broken text sweep, both languages
      const bad = [];
      for (const lg of ["en", "ar"]) {
        if (doc.documentElement.lang !== lg) doc.getElementById("lang-btn").click();
        for (const r of ["#/overview", "#/next", "#/history", ...D.activities.map((a) => "#/history/" + a.id)]) {
